 static Report report;static HomePage home;static HomeLevelFlow flow;static GameplayLoadingPage page;static PlayerProfileHost host;static PreLevelModal modal;
 static double began,next;static int index,phase,first,previous,locale;static PreLevelTicket oldTicket,newTicket;static int oldGeneration,newGeneration,lastReadyFrame=-1;static string chosenTip;static int[] initialStock;static int initialLives;static bool sawHeld;
