        static EditorWindow View()=>EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView"));
        static object Group(){var a=typeof(Editor).Assembly;var t=a.GetType("UnityEditor.GameViewSizes");var instance=typeof(ScriptableSingleton<>).MakeGenericType(t).GetProperty("instance",BindingFlags.Public|BindingFlags.Static).GetValue(null);return t.GetMethod("GetGroup").Invoke(instance,new[]{Enum.Parse(a.GetType("UnityEditor.GameViewSizeGroupType"),EditorUserBuildSettings.activeBuildTarget==BuildTarget.Android?"Android":"Standalone")});}
        static void Capture(string file){
            // Header effects belong to Home. The older screenshot helper calls
            // SetChapterBackground/Reflow mid-capture, which cancels those effects.
            var canvases=UnityEngine.Object.FindObjectsByType<Canvas>(UnityEngine.FindObjectsSortMode.InstanceID).Where(c=>c.isActiveAndEnabled&&c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray();var cameras=canvases.Select(c=>c.worldCamera).ToArray();var distances=canvases.Select(c=>c.planeDistance).ToArray();var go=new GameObject("Gameplay loading native capture camera");go.transform.position=new Vector3(-10000,0,-10);var camera=go.AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;var previousTarget=RenderTexture.active;var target=RenderTexture.GetTemporary(Screen.width,Screen.height,24,RenderTextureFormat.ARGB32);Texture2D pixels=null;
            try{camera.targetTexture=target;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=1;}Canvas.ForceUpdateCanvases();camera.Render();Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;pixels=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);pixels.ReadPixels(new Rect(0,0,target.width,target.height),0,0);pixels.Apply();File.WriteAllBytes(Path.Combine(Output,file),pixels.EncodeToPNG());report.frames.Add(file);}
            finally{for(int n=0;n<canvases.Length;n++){canvases[n].renderMode=RenderMode.ScreenSpaceOverlay;canvases[n].worldCamera=cameras[n];canvases[n].planeDistance=distances[n];}RenderTexture.active=previousTarget;RenderTexture.ReleaseTemporary(target);if(pixels)UnityEngine.Object.Destroy(pixels);UnityEngine.Object.Destroy(go);Canvas.ForceUpdateCanvases();}
        }
 static GameplayLoadingR1Review(){if(SessionState.GetBool(Key,false)){report=new Report{utc=DateTime.UtcNow.ToString("o")};began=EditorApplication.timeSinceStartup;locale=GameLocale.Current;first=SessionState.GetInt(Key+".first",0);previous=SessionState.GetInt(Key+".previous",0);EditorApplication.update+=Tick;Application.logMessageReceived+=Log;}}
 public static void Prepare(){AssetDatabase.Refresh();Directory.CreateDirectory(Output);
  string path="Assets/HeartOfTheRain/Resources/HOTR_GameplayLoading/Design.asset";Directory.CreateDirectory(Path.GetDirectoryName(path));AssetDatabase.Refresh();var a=AssetDatabase.LoadAssetAtPath<GameplayLoadingAssets>(path);if(!a){a=ScriptableObject.CreateInstance<GameplayLoadingAssets>();AssetDatabase.CreateAsset(a,path);}
  a.sprites=AssetDatabase.FindAssets("t:Sprite",new[]{"Assets/HeartOfTheRain/App/GameplayLoadingDesign/Art"}).Select(g=>AssetDatabase.LoadAssetAtPath<Sprite>(AssetDatabase.GUIDToAssetPath(g))).ToArray();if(a.sprites.Length!=14||a.sprites.Any(s=>!s))throw new Exception("Expected14 supplied sprites");EditorUtility.SetDirty(a);AssetDatabase.SaveAssets();
