 public static void Run(){SessionState.SetBool(Key,true);EditorSceneManager.OpenScene("Assets/HeartOfTheRain/App/FirstStart/Scenes/M65_First_Start.unity");UnityEngine.Object.FindFirstObjectByType<FirstStartPage>().reviewAlways=true;var group=Group();first=(int)group.GetType().GetMethod("GetTotalCount").Invoke(group,null);previous=(int)View().GetType().GetProperty("selectedSizeIndex",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).GetValue(View());SessionState.SetInt(Key+".first",first);SessionState.SetInt(Key+".previous",previous);var a=typeof(Editor).Assembly;foreach(var s in Sizes){var v=Activator.CreateInstance(a.GetType("UnityEditor.GameViewSize"),BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance,null,new object[]{Enum.Parse(a.GetType("UnityEditor.GameViewSizeType"),"FixedResolution"),s.x,s.y,"HOTR Gameplay Loading R2"},null);group.GetType().GetMethod("AddCustomSize").Invoke(group,new[]{v});}EditorApplication.isPlaying=true;}
 static T Field<T>(object o,string n)=>(T)o.GetType().GetField(n,Private).GetValue(o);
 static void Invoke(string n,params object[] args)=>typeof(HomeLevelFlow).GetMethod(n,Private).Invoke(flow,args);
 static void Check(bool ok,string reason){report.checks++;if(!ok)throw new Exception(reason);}
