 static void LayoutChecks(int state){Canvas.ForceUpdateCanvases();var canvas=Field<Canvas>(page,"canvas");Check(canvas.sortingOrder>240&&canvas.GetComponent<CanvasGroup>().alpha==1,"Opaque overlay above prelevel");
  foreach(var t in canvas.GetComponentsInChildren<Text>().Where(t=>t.gameObject.activeInHierarchy)){
   Check(t.font&&t.text.All(c=>char.IsWhiteSpace(c)||t.font.HasCharacter(c)),"Native font coverage: "+t.text);Check(t.cachedTextGenerator.characterCountVisible>=t.text.Count(c=>!char.IsWhiteSpace(c)),"Native text drawn: "+t.text);
   var v=new Vector3[4];t.rectTransform.GetWorldCorners(v);Check(v.All(p=>p.x>=-.5f&&p.y>=-.5f&&p.x<=Screen.width+.5f&&p.y<=Screen.height+.5f),"Text inside viewport: "+t.name);Check(!t.raycastTarget,"Text does not block input");
  }
  var diagram=Field<RectTransform>(page,"diagram");if(diagram.gameObject.activeSelf){var v=new Vector3[4];diagram.GetWorldCorners(v);Check(v.All(p=>p.x>=0&&p.y>=0&&p.x<=Screen.width+.5f&&p.y<=Screen.height+.5f),"Diagram fits safe viewport");foreach(var image in diagram.GetComponentsInChildren<Image>()){
   Check(image.sprite&&image.color==Color.white&&!image.raycastTarget,"Separate untinted source art");var v2=new Vector3[4];image.rectTransform.GetWorldCorners(v2);Check(Vector3.Distance(v2[0],v2[3])<=image.sprite.rect.width+1&&Vector3.Distance(v2[0],v2[1])<=image.sprite.rect.height+1,"Native pixel budget: "+image.name);
  }}
  var pattern=Field<Image>(page,"pattern");Check(pattern.type==Image.Type.Tiled&&pattern.pixelsPerUnitMultiplier==1,"Raindrops tile instead of stretching");Check(pattern.sprite.pixelsPerUnit==400,"96 logical-unit repeat at reference PPU100");
  Check(!canvas.GetComponentsInChildren<Text>().Any(t=>t.text.Contains("%")||t.text.StartsWith("Level ")),"No fake progress or level label in R2");
  foreach(var b in canvas.GetComponentsInChildren<Button>())Check(b.GetComponent<RectTransform>().rect.height>=48,"Recovery touch target48");report.layouts++;
