 static void Tick(){try{
  if(EditorApplication.timeSinceStartup-began>300)throw new TimeoutException("Gameplay loading review timed out: "+index+" phase "+phase);if(!string.IsNullOrEmpty(report.error))throw new Exception(report.error);if(!EditorApplication.isPlaying||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.timeSinceStartup<next)return;
