  if(index<150){int dim=index/30,lang=index%30/6,state=index%6;bool failure=state>=3;int tip=state%3;if(Screen.width!=Sizes[dim].x||Screen.height!=Sizes[dim].y)return;GameLocale.Select(lang);
   if(phase==0){page.Begin(tip!=2,tip==0,tip==1);if(failure)page.ShowFailure();phase=1;next=EditorApplication.timeSinceStartup+.08;return;}
   LayoutChecks(state);if(lang==0||dim==0&&state==1||dim==0&&state==3)Capture($"View_{GameLocale.Codes[lang]}_{state}_{Screen.width}x{Screen.height}.png");phase=0;index++;if(index%30==0&&index<150)Size(index/30);if(index==150){page.Hide();Size(0);}return;
  }
  if(Screen.width!=393||Screen.height!=852)return;GameLocale.Select(0);
  if(index==150){
   Check(GameplayLoadingPage.SelectTip(false,true,true,"")==""&&GameplayLoadingPage.SelectTip(true,false,false,"")=="","Hints-off and no eligible item hide tips");Check(GameplayLoadingPage.SelectTip(true,true,true,"rain")=="orb"&&GameplayLoadingPage.SelectTip(true,true,true,"orb")=="rain","Avoid repeating where eligible");
   page.Hide();var fallbackObject=new GameObject("Missing loading art fixture");var fallback=fallbackObject.AddComponent<GameplayLoadingPage>();fallback.home=home;fallback.font=page.font;fallback.Begin(true,true,true);Check(!Field<RectTransform>(fallback,"diagram").gameObject.activeSelf&&fallback.IsVisible,"Native text fallback without decorative art");var bg=Field<Canvas>(fallback,"canvas").transform.Find("Sapphire background").GetComponent<Image>();Check(!bg.sprite&&bg.color.a==1&&bg.raycastTarget,"Missing-art fallback is opaque and input-blocking");Capture("Fallback_No_Art.png");fallback.Hide();UnityEngine.Object.Destroy(fallbackObject);
   home.State.reduceMotion=false;Time.timeScale=0;page.Begin(true,true,false);index++;next=EditorApplication.timeSinceStartup+.24;return;
  }
  if(index==151){var dots=Field<Text[]>(page,"dots");Check(dots.Select(d=>Mathf.RoundToInt(d.color.a*100)).Distinct().Count()>1,"Dots animate with gameplay timeScale zero");var pos=dots.Select(d=>d.rectTransform.anchoredPosition).ToArray();page.Begin(true,false,true,true);Check(page.Tip=="rain"&&dots.Select(d=>d.rectTransform.anchoredPosition).SequenceEqual(pos),"Retry retains tip and fixed dot positions");home.State.reduceMotion=true;index++;next=EditorApplication.timeSinceStartup+.1;return;}
  if(index==152){Check(Field<Text[]>(page,"dots").All(d=>d.color.a==1),"Reduced motion leaves dots visible");page.Hide();Time.timeScale=1;initialStock=host.Service.Read().starting;initialLives=host.Service.Read().lives;flow.Open(1);modal.Requested("toggle:0");int attempts=host.Service.Read().attempts.Count;modal.Requested("play");Check(page.IsVisible&&!modal.IsVisible&&flow.Preview.busy,"Overlay shown synchronously with accepted Play");Check(host.Service.Read().attempts.Count==attempts,"Render opportunity precedes profile/board work");oldTicket=Field<PreLevelTicket>(flow,"launchTicket");oldGeneration=Field<int>(flow,"launchGeneration");chosenTip=page.Tip;modal.Requested("play");Check(ReferenceEquals(oldTicket,Field<PreLevelTicket>(flow,"launchTicket")),"Duplicate Play ignored");oldTicket.powerKinds=new[]{999};index++;return;}
  if(index==153){if(!page.IsFailure)return;Check(!UnityEngine.Object.FindFirstObjectByType<GameplayScreen>(),"Failed partial gameplay destroyed before recovery");Check(host.Service.Read().attempts.Last().state=="Cancelled"&&host.Service.Read().lives==initialLives&&host.Service.Read().starting.SequenceEqual(initialStock),"Invalid grant cancels reservation without life/item debit");Check(flow.Preview.selected[0],"Selected booster retained");Capture("Connected_Failed_Grant.png");page.RetryRequested();Check(page.IsVisible&&!page.IsFailure&&page.Tip==chosenTip,"Retry keeps tip");newTicket=Field<PreLevelTicket>(flow,"launchTicket");newGeneration=Field<int>(flow,"launchGeneration");Check(newGeneration!=oldGeneration&&!ReferenceEquals(oldTicket,newTicket),"Retry uses new operation token");Invoke("FailLaunch",oldTicket,oldGeneration);Invoke("CompleteLaunch",oldTicket,oldGeneration);Check(ReferenceEquals(newTicket,Field<PreLevelTicket>(flow,"launchTicket")),"Late callbacks cannot cancel or complete retry");report.flow.Add("Invalid starting grant / cancellation / duplicate Play / retry / stale operation guard");index++;return;}
  if(index==154){var game=UnityEngine.Object.FindFirstObjectByType<GameplayScreen>();if(game&&page.IsVisible&&game.HasStartedWithPowers&&!sawHeld){Check(Field<bool>(game,"startingCreationPending"),"Creation animation held behind loading");sawHeld=true;}if(game&&game.InitializationComplete&&page.IsVisible&&Time.frameCount!=lastReadyFrame){lastReadyFrame=Time.frameCount;report.readyFrames++;}if(page.IsVisible)return;
   Check(game&&game.InitializationComplete&&game.HasStartedWithPowers&&!game.ReviewInputBlocked,"Immediate handoff after complete readiness");Check(sawHeld&&report.readyFrames<=1,"No dwell after readiness; creations held until visible");Check(host.Service.Read().attempts.Last().state=="Started"&&host.Service.Read().starting[0]==initialStock[0]-1&&host.Service.Read().lives==initialLives,"One starting item committed once, no life loss");Invoke("CompleteLaunch",newTicket,newGeneration);Check(game==UnityEngine.Object.FindFirstObjectByType<GameplayScreen>(),"Late duplicate completion cannot destroy launched gameplay");report.flow.Add("Ready handoff / creation hold / one-time start debit / duplicate completion");flow.ReturnHomeForReview();flow.Open(1);modal.Requested("toggle:1");modal.Requested("play");Field<PreLevelTicket>(flow,"launchTicket").powerKinds=new[]{999};index++;return;
  }
  if(index==155){if(!page.IsFailure)return;page.BackRequested();Check(!page.IsVisible&&modal.IsVisible&&!flow.Preview.busy&&flow.Preview.selected[1],"Back returns same preview and selected item after confirmed cleanup");Capture("Connected_Back_To_Level.png");modal.Requested("close");host.Service.Change(p=>{p.lives=0;p.livesRefillDueUnix=DateTimeOffset.UtcNow.ToUnixTimeSeconds()+1800;return true;});host.Refresh();flow.Open(1);modal.Requested("play");Check(!page.IsVisible&&!flow.Preview.busy,"No-lives rejection stays in prelevel");modal.Requested("close");host.Service.Change(p=>{p.lives=5;p.livesRefillDueUnix=0;return true;});host.Refresh();flow.Open(1);modal.Requested("toggle:1");modal.Requested("play");host.Service.Change(p=>{p.starting[1]=0;return true;});index++;return;}
  if(index==156){if(page.IsVisible)return;Check(modal.IsVisible&&!flow.Preview.busy&&flow.Preview.message==ProfileService.BoosterUnavailable,"Reservation rule rejection restores prelevel");report.flow.Add("Recovery Back / zero-life rejection / changed stock rejects without initialization");Finish(0);}
 }catch(Exception e){report.error=e.ToString();try{if(home)Capture("Failure.png");}catch(Exception){}Finish(1);}}
 static void Finish(int code){Time.timeScale=1;report.status=code==0?"PASS_NATIVE_GAMEPLAY_LOADING_R2":"FAIL_NATIVE_GAMEPLAY_LOADING_R2";Directory.CreateDirectory(Output);File.WriteAllText(Path.Combine(Output,"Native_Review.json"),JsonUtility.ToJson(report,true));EditorApplication.update-=Tick;Application.logMessageReceived-=Log;GameLocale.Select(locale);SessionState.EraseBool(Key);View().GetType().GetProperty("selectedSizeIndex",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).SetValue(View(),previous);var group=Group();for(int i=Sizes.Length-1;i>=0;i--)group.GetType().GetMethod("RemoveCustomSize").Invoke(group,new object[]{first+i});EditorApplication.Exit(code);}
